26: /// @brief RAII guard: unsubscribes current task from TWDT for scope lifetime,
27: ///        resubscribes on destruction. Matches OTAUpdateManager pattern
28: ///        (OTAUpdateManager.cpp:666-671).
29: /// @note The TWDT is a starvation detector. A task parked in select() during
30: ///       a network fetch is not the failure mode it exists to catch — that is
31: ///       already answered by the idle tasks. Unsubscription is safe here because:
32: ///       (1) DeadlineToken provides cooperative cancel,
33: ///       (2) Layer 1 bounds the transport at ~15s,
34: ///       (3) Layer 4 escalates via shutdown(fd) if the fetch overruns.
35: ///       See ADR: TWDT Supervision Strategy.
36: /// @warning Proxy-feeding (esp_timer calling esp_task_wdt_reset()) does NOT work:
37: ///          esp_task_wdt_reset() acts on the CALLING task's handle. From a timer
38: ///          context it either fails with ESP_ERR_NOT_FOUND or feeds the wrong entry.
39: struct TwdtFetchGuard {
40:     explicit TwdtFetchGuard() {
41:         esp_task_wdt_delete(NULL);
42:     }
43:     ~TwdtFetchGuard() {
44:         esp_task_wdt_add(NULL);
45:         esp_task_wdt_reset();
46:     }
47:     TwdtFetchGuard(const TwdtFetchGuard&) = delete;
48:     TwdtFetchGuard& operator=(const TwdtFetchGuard&) = delete;
49: };
