57: class FetchGuard {
58: public:
59:     FetchGuard(IDataSource* source, FetchContext& ctx, FrameworkSecureClient* secureClient, WiFiClient* plainClient)
60:         : _timer(nullptr) {
61:         bool useTls = source ? source->requiresTls() : true;
62:         
63:         if (useTls && secureClient) {
64:             secureClient->stop();
65:             secureClient->applyDeadline(ctx.deadline);
66:             ctx.client = secureClient;
67:         } else if (plainClient) {
68:             plainClient->stop();
69:             plainClient->setConnectionTimeout(
70:                 std::min(ctx.deadline.remainingMs(), FetchContext::CONNECT_TIMEOUT_MS));
71:             ctx.client = plainClient;
72:         }
73:         
74:         _escCtx.client = ctx.client;
75:         
76:         esp_timer_create_args_t timerArgs = {};
77:         timerArgs.callback = [](void* arg) {
78:             auto* e = static_cast<EscalationCtx*>(arg);
79:             int fd = e->client ? e->client->fd() : -1;
80:             if (fd >= 0) {
81:                 shutdown(fd, SHUT_RDWR);
82:                 ESP_LOGW(TAG, "Fetch deadline exceeded — socket shutdown forced");
83:             } else {
84:                 ESP_LOGE(TAG, "Fetch deadline exceeded with no framework socket in flight — "
85:                               "source is not using ctx.client and cannot be interrupted");
86:             }
87:         };
88:         timerArgs.arg = &_escCtx;
89:         timerArgs.name = "fetch_deadline";
90: 
91:         uint32_t remaining = ctx.deadline.remainingMs();
92:         if (remaining > 0) {
93:             esp_timer_create(&timerArgs, &_timer);
94:             esp_timer_start_once(_timer, (uint64_t)remaining * 1000);
95:         }
96:     }
97: 
98:     ~FetchGuard() {
99:         if (_timer) {
100:             esp_timer_stop(_timer);
101:             esp_timer_delete(_timer);
102:             _timer = nullptr;
103:         }
104:     }
105: 
106: private:
107:     esp_timer_handle_t _timer;
108:     EscalationCtx _escCtx;
109:     TwdtFetchGuard _wdtGuard;
110: };
