188:     // DRAM (not PSRAM) is required because SPI flash operations (used by some
189:     // data sources) assert when the task stack is in PSRAM.
190:     ESP_LOGI(TAG, "Creating worker task (stack=%u, priority=5, core=any, DRAM)",
191:              (unsigned)_workerStackSize);
