210: bool DataManager::queueDataJob(std::function<void(const FetchContext&)> job, const DataJobOptions& options) {
211:     if (!_jobQueue || !job) return false;
212: 
213:     DataJobEntry* entry = new (std::nothrow) DataJobEntry{
214:         std::move(job),
215:         options
216:     };
217:     if (!entry) {
218:         ESP_LOGE(TAG, "Failed to allocate job entry for '%s'", options.tag);
219:         return false;
220:     }
221: 
222:     if (xQueueSend(_jobQueue, &entry, 0) != pdTRUE) {
223:         ESP_LOGW(TAG, "Job queue full — dropping '%s' (%d pending)",
224:                  options.tag, (int)getQueuedJobCount());
225:         delete entry;
226:         return false;
227:     }
228: 
229:     ESP_LOGD(TAG, "Queued data job: '%s' (urgent=%s)", options.tag,
230:              options.urgent ? "yes" : "no");
231: 
232:     if (_workerTask) {
233:         xTaskNotifyGive(_workerTask);
234:     }
235: 
236:     return true;
237: }
