244: void DataManager::drainJobs(bool urgentOnly) {
245:     if (!_jobQueue) return;
246: 
247:     // Snapshot current queue depth to bound this drain pass (F8).
248:     // Jobs enqueued during execution are deferred to the next iteration.
249:     size_t maxDrain = (size_t)uxQueueMessagesWaiting(_jobQueue);
250:     if (maxDrain == 0) return;
251: 
252:     // Collect non-matching entries to re-queue after the scan (F5).
253:     // Stack-allocated — bounded by JOB_QUEUE_DEPTH.
254:     DataJobEntry* deferred[JOB_QUEUE_DEPTH];
255:     size_t deferredCount = 0;
256:     size_t drained = 0;
257: 
258:     DataJobEntry* entry = nullptr;
259:     while (drained < maxDrain && xQueueReceive(_jobQueue, &entry, 0) == pdTRUE) {
260:         drained++;
261:         if (urgentOnly && !entry->options.urgent) {
262:             // Not urgent — defer for later pass
263:             deferred[deferredCount++] = entry;
264:             continue;
265:         }
266: 
267:         ESP_LOGD(TAG, "Executing data job: '%s'", entry->options.tag);
268: 
269:         uint32_t jobStart = getCurrentTimeMs();
270: 
271:         DeadlineToken token(jobStart + FetchContext::FETCH_TOTAL_TIMEOUT_MS, [this]() { return getCurrentTimeMs(); });
272:         FetchContext ctx{token};
273: #ifdef ESP_PLATFORM
274:         FetchGuard fg(nullptr, ctx,
275:                       entry->options.requiresTls ? _secureClient : nullptr,
276:                       entry->options.requiresTls ? nullptr : _plainClient);
277: #endif
278: 
279:         entry->job(ctx);
280:         if (ctx.deadline.isExpired()) {
281:             ESP_LOGW(TAG, "Data job '%s' exceeded deadline", entry->options.tag);
282:         }
283: 
284:         uint32_t elapsed = getCurrentTimeMs() - jobStart;
285:         if (entry->options.warnAfterMs > 0 && elapsed > entry->options.warnAfterMs) {
286:             ESP_LOGW(TAG, "Data job '%s' took %lu ms (warn threshold: %lu ms)",
287:                      entry->options.tag, (unsigned long)elapsed,
288:                      (unsigned long)entry->options.warnAfterMs);
289:         }
290: 
291:         delete entry;
292:     }
293: 
294:     // Re-queue deferred entries, preserving their order relative to each other.
295:     // Caveat: jobs enqueued by another task *during* this drain are already at
296:     // the back of the queue, so they will run before these deferred entries.
297:     // Strict global FIFO is therefore not guaranteed across a drain boundary.
298:     for (size_t i = 0; i < deferredCount; i++) {
299:         if (xQueueSend(_jobQueue, &deferred[i], 0) != pdTRUE) {
300:             ESP_LOGW(TAG, "Failed to re-queue deferred job '%s' — dropping",
301:                      deferred[i]->options.tag);
302:             delete deferred[i];
303:         }
304:     }
305: }
