352: // ---------------------------------------------------------------------------
353: // Health state machine (#128)
354: //
355: // Failure is a state, not a reset. Every transition below is driven by the
356: // UpdateStatus the source returned — these codes already distinguish cases the
357: // scheduler should treat differently, and the distinction was previously unused.
358: // ---------------------------------------------------------------------------
359: void DataManager::recordFetchOutcome(SourceRecord& r, UpdateStatus status, uint32_t nowMs) {
360:     SourceHealthState oldState = r.state;
361: 
362:     // lastStatus is stamped for ALL statuses — surfaces can show *why* nothing is happening
363:     r.lastStatus = status;
364: 
365:     // lastAttemptMs is NOT stamped for Skipped — it was not a genuine attempt
366:     if (status != UpdateStatus::Skipped) r.lastAttemptMs = nowMs;
367: 
368:     switch (status) {
369:     case UpdateStatus::Skipped:
370:         return;   // health, backoff, everSucceeded all untouched
371: 
372:     case UpdateStatus::Success:
373:     case UpdateStatus::NoChange:
374:         // Recovery is unconditional: one success clears the whole failure history,
375:         // including from Quarantined (the probe worked) and Suspended (a priority
376:         // fetch after the user fixed the credentials). A later failure therefore
377:         // starts a fresh series from the base delay, not from the old ceiling.
378:         r.state                = SourceHealthState::Healthy;
379:         r.consecutiveFailures  = 0;
380:         r.currentBackoffMs     = 0;
381:         r.nextAttemptMs        = 0;
382:         r.backoffActive        = false;
383:         r.backoffFromRateLimit = false;
384:         r.lastSuccessMs        = nowMs;
385:         r.everSucceeded        = true;
386: 
387:         if (oldState != r.state) {
388:             r._hasPendingHealthTransition = true;
389:             r._healthPayload = { r.source->getSourceName(), r.state };
390:         }
391:         return;
392: 
393:     case UpdateStatus::AuthError:
394:         // Terminal until someone intervenes. Credentials do not fix themselves,
395:         // so retrying on a timer only burns the radio and the remote's rate limit.
396:         // Exit is resetSourceHealth() or an explicit priority fetch.
397:         r.state             = SourceHealthState::Suspended;
398:         if (r.consecutiveFailures < UINT16_MAX) r.consecutiveFailures++;
399:         r.currentBackoffMs  = 0;
400:         r.nextAttemptMs     = 0;
401:         r.backoffActive     = false;
402:         
403:         if (oldState != r.state) {
404:             r._hasPendingHealthTransition = true;
405:             r._healthPayload = { r.source->getSourceName(), r.state };
406:         }
407: 
408:         ESP_LOGE(TAG, "Source '%s' SUSPENDED after auth failure — will not retry until reset",
409:                  r.source->getSourceName());
410:         return;
411: 
412:     case UpdateStatus::RateLimited: {
413:         // The peer is reachable and answering; we are simply asking too often.
414:         // Back off, but do not count it toward quarantine — this is not a fault
415:         // in the source, and quarantining a working peer would be wrong.
416:         //
417:         // A change of cause restarts the series: a source that has been rate-
418:         // limited up to the ceiling should not inherit that delay for its first
419:         // genuine failure, and vice versa. Without this the two policies interfere,
420:         // and one FetchError on a peer that was answering thirty seconds ago
421:         // quarantines it immediately.
422:         uint32_t effectiveCap = std::max(r.source ? r.source->getMaxBackoffMs() : HEALTH_BACKOFF_CAP_MS, HEALTH_BACKOFF_BASE_MS);
423:         r.currentBackoffMs = (!r.backoffActive || !r.backoffFromRateLimit)
424:             ? HEALTH_BACKOFF_BASE_MS
425:             : std::min(r.currentBackoffMs * 2, effectiveCap);
426:         r.nextAttemptMs        = nowMs + r.currentBackoffMs;
427:         r.backoffActive        = true;
428:         r.backoffFromRateLimit = true;
429:         if (r.state == SourceHealthState::Healthy || r.state == SourceHealthState::Unknown) {
430:             r.state = SourceHealthState::Degraded;
431:         }
432:         
433:         if (oldState != r.state) {
434:             r._hasPendingHealthTransition = true;
435:             r._healthPayload = { r.source->getSourceName(), r.state };
436:         }
437: 
438:         ESP_LOGW(TAG, "Source '%s' rate-limited — backing off %lu ms",
439:                  r.source->getSourceName(), (unsigned long)r.currentBackoffMs);
440:         return;
441:     }
442: 
443:     case UpdateStatus::FetchError:
444:     case UpdateStatus::ParseError:
445:     default:
446:         break;
447:     }
448: 
449:     // --- Genuine failure: count it, back off, quarantine at the ceiling ---
450:     // Saturating: at ceiling probes an unsaturated uint16_t would take
451:     // ~682 days to wrap, but wrapping to 0 would read as "healthy" to a consumer.
452:     if (r.consecutiveFailures < UINT16_MAX) r.consecutiveFailures++;
453:     uint32_t effectiveCap = std::max(r.source ? r.source->getMaxBackoffMs() : HEALTH_BACKOFF_CAP_MS, HEALTH_BACKOFF_BASE_MS);
454:     r.currentBackoffMs = (!r.backoffActive || r.backoffFromRateLimit)
455:         ? HEALTH_BACKOFF_BASE_MS
456:         : std::min(r.currentBackoffMs * 2, effectiveCap);
457:     r.nextAttemptMs        = nowMs + r.currentBackoffMs;
458:     r.backoffActive        = true;
459:     r.backoffFromRateLimit = false;
460: 
461:     // Quarantined is not "given up" — it is "probing at the backoff cap",
462:     // so an unreachable peer that comes back is picked up without
463:     // anyone touching the device. Quarantining is triggered after
464:     // QUARANTINE_FAILURE_THRESHOLD consecutive failures, decoupled from backoff cap.
465:     r.state = (r.consecutiveFailures >= QUARANTINE_FAILURE_THRESHOLD)
466:         ? SourceHealthState::Quarantined
467:         : SourceHealthState::Degraded;
468: 
469:     if (oldState != r.state) {
470:         r._hasPendingHealthTransition = true;
471:         r._healthPayload = { r.source->getSourceName(), r.state };
472:     }
473: 
474:     ESP_LOGW(TAG, "Source '%s' %s (status=%d, %u consecutive) — next attempt in %lu ms%s",
475:              r.source->getSourceName(),
476:              r.state == SourceHealthState::Quarantined ? "QUARANTINED" : "degraded",
477:              (int)status, (unsigned)r.consecutiveFailures,
478:              (unsigned long)r.currentBackoffMs,
479:              r.everSucceeded ? "" : " (has never connected)");
480: }
