519: void DataManager::resetSourceHealth(IDataSource* source) {
520:     if (!source) return;
521:     MutexLock lock(_registryMutex);
522:     for (auto& r : _registry) {
523:         if (r.source == source) {
524:             ESP_LOGI(TAG, "Health reset for source: %s", source->getSourceName());
525:             // Unknown in both branches, not Healthy-if-it-ever-worked. Healthy is
526:             // documented as "last attempt succeeded", and after a reset following
527:             // a string of failures the last attempt did not succeed — reporting
528:             // Healthy would tell the portal the source is fine when nothing has
529:             // been verified. Reset means "clear the penalty box and try again",
530:             // which is exactly Unknown. everSucceeded is preserved, so the
531:             // never-connected distinction survives.
532:             r.state                = SourceHealthState::Unknown;
533:             r.lastStatus           = UpdateStatus::Success;  // no verdict; see SourceHealth::lastStatus
534:             r.consecutiveFailures  = 0;
535:             r.currentBackoffMs     = 0;
536:             r.nextAttemptMs        = 0;
537:             r.backoffActive        = false;
538:             r.backoffFromRateLimit = false;
539:             return;
540:         }
541:     }
542: }
