551: void DataManager::processNext() {
552: #ifdef ESP_PLATFORM
553:     // On target the worker task drives this loop. Calling from any other
554:     // task would run blocking network I/O on the caller (e.g. loopTask)
555:     // without supervision, and corrupt the caller's TWDT state via
556:     // startFetchWatchdog()/stopFetchWatchdog(). Refuse outright. See #156.
557:     if (xTaskGetCurrentTaskHandle() != _workerTask) {
558:         ESP_LOGE(TAG, "processNext() called from %s — native/test only, "
559:                  "the worker task drives this loop on target",
560:                  pcTaskGetName(NULL));
561:         return;
562:     }
563: #endif
564:     drainJobs(true);
565:     executeLoop();
566:     drainJobs(false);
567: }
