572: void DataManager::workerTaskLoop(void* param) {
573:     DataManager* manager = static_cast<DataManager*>(param);
574: 
575:     // Register with Task Watchdog Timer — this is a long-running worker loop
576:     // that must feed the watchdog periodically to avoid triggering a reset.
577:     esp_task_wdt_add(NULL);
578: 
579:     TickType_t lastWatermarkLog = 0;
580: 
581:     while (true) {
582:         manager->drainJobs(true);
583:         manager->executeLoop();
584:         manager->drainJobs(false);
585: 
586:         // Feed the watchdog after each fetch cycle
587:         esp_task_wdt_reset();
588: 
589:         // Periodic stack watermark telemetry — log every 60s to avoid spam.
590:         // Data gathered here informs future stack reduction / PSRAM migration.
591:         // Uses raw tick counts with pdMS_TO_TICKS to avoid multiply overflow.
592:         TickType_t now = xTaskGetTickCount();
