608: void DataManager::executeLoop() {
609:     // NOTE: _appRunning is deliberately NOT a blanket early return.
610:     //
611:     // It used to be, and that silently voided two guarantees. A source that backs
612:     // a startup precondition forms a circle with the state machine: the precondition blocks
613:     // RUNNING, RUNNING enables fetching, and fetching is what would satisfy the
614:     // precondition. Once such a source failed into Quarantined, Application regressed to
615:     // CONFIGURING and cleared _appRunning — so the 15-minute self-healing probe
616:     // never ran again, the gate could never re-satisfy, and _appRunning could
617:     // never return to true. The device sat there permanently, and the peer coming
618:     // back changed nothing because there was no probe left to notice.
619:     //
620:     // The same early return sat above the priorityRequested check, so
621:     // requestPriorityFetch() was inert in precisely the state where a source
622:     // needs recovering — the user corrects the address in the portal, we request
623:     // a fetch, and nothing happens.
624:     //
625:     // The gate is now applied per-source, below both escape hatches.
626:     // _appRunning was deliberately removed. See the NOTE above for the full rationale.
627:     // This constant preserves the per-source gating logic below (fetchesWhileConfiguring)
628:     // without the global blanket early return that caused the circular-dependency deadlock.
629:     // The variable reads as "all sources allowed" and the per-source checks provide the
630:     // actual gating. If a global gate is ever needed again, it should be an atomic bool
631:     // driven by Application state transitions, not a removed setter.
632:     const bool appRunning = true;
633: 
634:     MutexLock lock(_registryMutex);
635:     if (_registry.empty()) return;
636: 
637:     uint32_t now = getCurrentTimeMs();
638:     int bestIndex = -1;
639:     bool foundPriority = false;
640:     PriorityTier bestTier = PriorityTier::Low;
641: 
642:     for (size_t i = 0; i < _registry.size(); ++i) {
643:         auto& r = _registry[i];
644: 
645:         // Handle explicit priority requests.
646:         // A priority fetch deliberately ignores backoff, health state AND the
647:         // app-running gate: it represents a person asking for this now, usually
648:         // straight after correcting the thing that was broken. It is the manual
649:         // recovery path for a source no timer will retry, so it must work in
650:         // CONFIGURING — that is the state a broken source puts the device into.
651:         if (r.priorityRequested) {
652:             bestIndex = i;
653:             foundPriority = true;
654:             break; // Immediate selection
655:         }
656: 
657:         // Scheduled fetching is gated on RUNNING, except for sources that
658:         // explicitly opt out because they back a config gate (see
659:         // IDataSource::fetchesWhileConfiguring).
660:         if (!appRunning && !r.source->fetchesWhileConfiguring()) continue;
661: 
662:         // Health backoff gate (#128). Suspended sources are excluded outright —
663:         // they are not on a timer at all.
664:         if (r.state == SourceHealthState::Suspended) continue;
665: 
666:         // Rollover-safe comparison. millis() wraps at ~49.7 days, which is
667:         // ordinary uptime here. An absolute `now < nextAttemptMs` breaks in both
668:         // directions across a wrap: a deadline computed just before one wraps to a
669:         // small value and skips backoff entirely, and afterwards a small `now`
670:         // against a large pre-wrap deadline blocks the source for up to ~49 days.
671:         // Signed difference is the same idiom the `due` computation below uses.
672:         if (r.backoffActive && (int32_t)(now - r.nextAttemptMs) < 0) continue;
673: 
674:         // Handle scheduled execution based on interval and tier
675:         bool due = (r.lastFetchTimeMs == 0) || (now - r.lastFetchTimeMs >= r.source->getUpdateIntervalMs());
676: 
677:         if (due && !foundPriority) {
678:             // Smaller priority enum values indicate higher priority (HIGH = 0, LOW = 2)
679:             if (bestIndex == -1 || r.source->getPriorityTier() < bestTier) {
680:                 bestIndex = i;
681:                 bestTier = r.source->getPriorityTier();
682:             }
683:         }
684:     }
685: 
686:     if (bestIndex != -1) {
687:         auto& r = _registry[bestIndex];
688:         r.priorityRequested = false;
689: 
690:         // Extract the target source before releasing the lock
691:         IDataSource* fetchTarget = r.source;
692:         ESP_LOGD(TAG, "Selected source for fetch: %s", fetchTarget->getSourceName());
693: 
694:         // Unlock mutex during fetch to prevent holding the lock during potentially long network calls
695:         if (_registryMutex) xSemaphoreGive(_registryMutex);
696: 
697:         // --- Execute the fetch cycle ---
698:         uint32_t fetchStart = getCurrentTimeMs();
699: 
700:         DeadlineToken token(fetchStart + FetchContext::FETCH_TOTAL_TIMEOUT_MS, [this]() { return getCurrentTimeMs(); });
701:         FetchContext ctx{token};
702: #ifdef ESP_PLATFORM
703:         FetchGuard fg(fetchTarget, ctx, _secureClient, _plainClient);
704: #endif
705: 
706:         UpdateStatus result = fetchTarget->fetchUpdate(ctx);
707:         if (ctx.deadline.isExpired()) {
708:             ESP_LOGW(TAG, "Fetch for '%s' exceeded deadline — marking as FetchError",
709:                      fetchTarget->getSourceName());
710:         }
711:         if (ctx.deadline.isExpired() && result == UpdateStatus::Success) {
712:             result = UpdateStatus::FetchError;
713:         }
714: 
715:         uint32_t fetchDuration = getCurrentTimeMs() - fetchStart;
716:         if (fetchDuration > 15000) {
717:             ESP_LOGW(TAG, "fetchUpdate() for source '%s' took %lu ms — consider reducing client timeout",
718:                      fetchTarget->getSourceName(), (unsigned long)fetchDuration);
719:         }
720: 
721:         // Re-acquire mutex to update state
722:         if (_registryMutex) xSemaphoreTake(_registryMutex, portMAX_DELAY);
723: 
724:         bool publishHealth = false;
725: 
726:         // Ensure source is still registered before updating tracking data.
727:         // A source can be unregistered while its fetch is in flight, in which
728:         // case the outcome is simply discarded along with its health.
729:         for (auto& r2 : _registry) {
730:             if (r2.source == fetchTarget) {
731:                 // One clock read for both: lastFetchTimeMs gates the next
732:                 // scheduling pass and lastAttemptMs gates backoff, and there is no
733:                 // reason for them to disagree by the width of two millis() calls.
734:                 uint32_t completedAt = getCurrentTimeMs();
735:                 r2.lastFetchTimeMs = completedAt;
736:                 recordFetchOutcome(r2, result, completedAt);
737:                 
738:                 if (r2._hasPendingHealthTransition) {
739:                     publishHealth = true;
740:                     _publishPayload = r2._healthPayload;
741:                     r2._hasPendingHealthTransition = false;
742:                 }
743:                 break;
744:             }
745:         }
746:         
747:         // Temporarily release lock to publish event safely
748:         if (_registryMutex) xSemaphoreGive(_registryMutex);
749: 
750:         if (publishHealth && _eventBus) {
751:             _eventBus->publish(ApplicationEvents::DATA_SOURCE_HEALTH, &_publishPayload);
752:         }
753: 
754:         // Re-acquire lock to maintain MutexLock destructor balance
755:         if (_registryMutex) xSemaphoreTake(_registryMutex, portMAX_DELAY);
756:     }
