131: /**
132:  * @brief Follow HTTP redirects and return the final response code.
133:  *
134:  * Loops up to kMaxRedirects times. Each iteration opens a new HTTP request
135:  * with download headers (User-Agent, Cache-Control, Accept,
136:  * Authorization) and disables auto-redirect to
137:  * manually follow 301/302/307/308 responses via the Location header.
138:  *
139:  * Uses HTTP/1.0 to avoid chunked transfer encoding complications on
140:  * constrained devices.
141:  *
142:  * @param client Active WiFiClient reference.
143:  * @param http   HTTPClient instance to use for requests.
144:  * @param url    Initial URL to fetch.
145:  * @param token  Optional GitHub access token.
146:  * @return HTTP status code on success, or -1 on redirect exhaustion/failure.
147:  */
148: int OTADownloadEngine::followRedirects(WiFiClient& client, HTTPClient& http,
149:                                         const std::string& url, const std::string& token) {
150:     std::string currentUrl = url;
151: 
152:     for (int hop = 0; hop < kMaxRedirects; hop++) {
153:         // --- Begin HTTP request for this hop ---
154:         if (!http.begin(client, String(currentUrl.c_str()))) {
155:             ESP_LOGE(TAG, "http.begin() failed for URL: %s", currentUrl.c_str());
156:             return -1;
157:         }
158: 
159:         // Configure headers for GitHub release asset API
160:         http.useHTTP10(true);
161:         http.setTimeout(httpTimeout_);
162:         http.setFollowRedirects(HTTPC_DISABLE_FOLLOW_REDIRECTS);
163:         http.setUserAgent("ESP32-http-Update");
164:         http.addHeader("Cache-Control", "no-cache");
165:         http.addHeader("Accept", "application/octet-stream");
166:         if (!token.empty()) {
167:             http.addHeader("Authorization", String(("Bearer " + token).c_str()));
168:         }
169: 
170: 
171:         int code = http.GET();
172: 
173:         // --- Check for redirect responses ---
174:         if (code == HTTP_CODE_MOVED_PERMANENTLY  || code == HTTP_CODE_FOUND ||
175:             code == HTTP_CODE_TEMPORARY_REDIRECT || code == HTTP_CODE_PERMANENT_REDIRECT) {
176:             String newUrl = http.getLocation();
177:             http.end();
178: 
179:             if (newUrl.length() == 0) {
180:                 ESP_LOGE(TAG, "Redirect response but empty Location header at hop %d", hop + 1);
181:                 return -1;
182:             }
183: 
184:             ESP_LOGD(TAG, "Redirect hop %d/%d → %s", hop + 1, kMaxRedirects, newUrl.c_str());
185:             currentUrl = newUrl.c_str();
186:             continue;
187:         }
188: 
189:         // --- Non-redirect response: return the code with connection open ---
190:         return code;
191:     }
192: 
193:     // Exhausted all redirect hops
194:     ESP_LOGE(TAG, "Exceeded maximum redirect hops (%d)", kMaxRedirects);
195:     return -1;
196: }
